insert into public.mail_templates (key, subject, body_html, active) values
  ('jobfair_cv_confirmed', $subj$Jobmesse bei 25hours - komm vorbei$subj$, $body$<html><body style="margin:0;padding:0;background:#eef2f3;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f3;padding:18px 0;"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;"><tr><td style="background:#0F5661;padding:22px 26px;"><div style="font-size:23px;font-weight:bold;color:#ffffff;letter-spacing:.02em;">25hours</div><div style="font-size:12.5px;color:#ffffff;opacity:.85;margin-top:3px;">Jobmesse · Recruiting Prishtina</div></td></tr><tr><td style="padding:22px 26px 4px;font-size:15.5px;color:#0f2830;font-weight:bold;">Lieber {{first_name}},</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">danke, dass du deine Bewerbung bei 25hours vollständig eingereicht hast. Aus unserem Büro in Pristina übernehmen wir den Kundenservice für namhafte deutsche Unternehmen aus der Reise- und Telekommunikationsbranche.</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">Deine Unterlagen liegen uns vor, und wir würden dich gerne persönlich kennenlernen. Komm zu unserer Jobmesse, es gibt kostenlose Getränke und Fingerfood.</td></tr><tr><td style="padding:6px 26px 4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f6f7;border-left:4px solid #0F5661;border-radius:10px;"><tr><td style="padding:16px 18px;"><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin-bottom:6px;">Wann</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;font-weight:bold;">Dienstag, 08.09.26, 17.00 bis 19.00 Uhr<br>Mittwoch, 09.09.26, 17.00 bis 19.00 Uhr</div><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin:14px 0 6px;">Wo</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;">Restaurant MeetPoint, Dukagjini Residence, Hyrja A,<br>Rr. Xhevdet Doda, Prishtine 10000</div></td></tr></table></td></tr><tr><td style="padding:18px 26px 4px;font-size:15px;line-height:1.6;color:#1f2937;">Komm einfach vorbei. Wir freuen uns, dich kennenzulernen.</td></tr><tr><td style="padding:16px 26px 22px;"><div style="font-size:15px;font-weight:bold;color:#0f2830;">Antonia Huber</div><div style="font-size:13px;color:#5b6b70;">Head of Recruiting</div><div style="font-size:13px;color:#5b6b70;">25hours</div></td></tr><tr><td style="padding:2px 26px 22px;font-size:11px;color:#9ca3af;line-height:1.5;border-top:1px solid #eef2f3;">Diese Einladung kommt von 25hours Recruiting, Prishtina. Antworten gehen an recruiting@25hrs.net.</td></tr></table></td></tr></table></body></html>$body$, true)
insert into public.mail_templates (key, subject, body_html, active) values
  ('jobfair_invited', $subj$Jobmesse bei 25hours - komm vorbei$subj$, $body$<html><body style="margin:0;padding:0;background:#eef2f3;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f3;padding:18px 0;"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;"><tr><td style="background:#0F5661;padding:22px 26px;"><div style="font-size:23px;font-weight:bold;color:#ffffff;letter-spacing:.02em;">25hours</div><div style="font-size:12.5px;color:#ffffff;opacity:.85;margin-top:3px;">Jobmesse · Recruiting Prishtina</div></td></tr><tr><td style="padding:22px 26px 4px;font-size:15.5px;color:#0f2830;font-weight:bold;">Lieber {{first_name}},</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">wir hatten dich bereits zu einem Gespräch eingeladen, konnten dich aber noch nicht persönlich treffen. Aus unserem Büro in Pristina übernehmen wir den Kundenservice für namhafte deutsche Unternehmen aus der Reise- und Telekommunikationsbranche.</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">Wir geben dir gerne eine zweite Gelegenheit. Komm einfach zu unserer Jobmesse, ohne Termin, ohne Anmeldung.</td></tr><tr><td style="padding:6px 26px 4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f6f7;border-left:4px solid #0F5661;border-radius:10px;"><tr><td style="padding:16px 18px;"><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin-bottom:6px;">Wann</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;font-weight:bold;">Dienstag, 08.09.26, 17.00 bis 19.00 Uhr<br>Mittwoch, 09.09.26, 17.00 bis 19.00 Uhr</div><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin:14px 0 6px;">Wo</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;">Restaurant MeetPoint, Dukagjini Residence, Hyrja A,<br>Rr. Xhevdet Doda, Prishtine 10000</div></td></tr></table></td></tr><tr><td style="padding:18px 26px 4px;font-size:15px;line-height:1.6;color:#1f2937;">Komm einfach vorbei. Wir freuen uns, dich kennenzulernen.</td></tr><tr><td style="padding:16px 26px 22px;"><div style="font-size:15px;font-weight:bold;color:#0f2830;">Antonia Huber</div><div style="font-size:13px;color:#5b6b70;">Head of Recruiting</div><div style="font-size:13px;color:#5b6b70;">25hours</div></td></tr><tr><td style="padding:2px 26px 22px;font-size:11px;color:#9ca3af;line-height:1.5;border-top:1px solid #eef2f3;">Diese Einladung kommt von 25hours Recruiting, Prishtina. Antworten gehen an recruiting@25hrs.net.</td></tr></table></td></tr></table></body></html>$body$, true)
insert into public.mail_templates (key, subject, body_html, active) values
  ('jobfair_no_contact', $subj$Jobmesse bei 25hours - komm vorbei$subj$, $body$<html><body style="margin:0;padding:0;background:#eef2f3;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f3;padding:18px 0;"><tr><td align="center"><table role="presentation" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;"><tr><td style="background:#0F5661;padding:22px 26px;"><div style="font-size:23px;font-weight:bold;color:#ffffff;letter-spacing:.02em;">25hours</div><div style="font-size:12.5px;color:#ffffff;opacity:.85;margin-top:3px;">Jobmesse · Recruiting Prishtina</div></td></tr><tr><td style="padding:22px 26px 4px;font-size:15.5px;color:#0f2830;font-weight:bold;">Lieber {{first_name}},</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">wir haben versucht, dich telefonisch zu erreichen, hatten aber leider kein Glück. Aus unserem Büro in Pristina übernehmen wir den Kundenservice für namhafte deutsche Unternehmen aus der Reise- und Telekommunikationsbranche.</td></tr><tr><td style="padding:0 26px 14px;font-size:15px;line-height:1.62;color:#1f2937;">Falls du weiterhin Interesse hast, komm einfach vorbei. Kein Anruf nötig, kein Termin.</td></tr><tr><td style="padding:6px 26px 4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f6f7;border-left:4px solid #0F5661;border-radius:10px;"><tr><td style="padding:16px 18px;"><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin-bottom:6px;">Wann</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;font-weight:bold;">Dienstag, 08.09.26, 17.00 bis 19.00 Uhr<br>Mittwoch, 09.09.26, 17.00 bis 19.00 Uhr</div><div style="font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:.06em;color:#0F5661;margin:14px 0 6px;">Wo</div><div style="font-size:14.5px;color:#1f2937;line-height:1.6;">Restaurant MeetPoint, Dukagjini Residence, Hyrja A,<br>Rr. Xhevdet Doda, Prishtine 10000</div></td></tr></table></td></tr><tr><td style="padding:18px 26px 4px;font-size:15px;line-height:1.6;color:#1f2937;">Komm einfach vorbei. Wir freuen uns, dich kennenzulernen.</td></tr><tr><td style="padding:16px 26px 22px;"><div style="font-size:15px;font-weight:bold;color:#0f2830;">Antonia Huber</div><div style="font-size:13px;color:#5b6b70;">Head of Recruiting</div><div style="font-size:13px;color:#5b6b70;">25hours</div></td></tr><tr><td style="padding:2px 26px 22px;font-size:11px;color:#9ca3af;line-height:1.5;border-top:1px solid #eef2f3;">Diese Einladung kommt von 25hours Recruiting, Prishtina. Antworten gehen an recruiting@25hrs.net.</td></tr></table></td></tr></table></body></html>$body$, true)
